const prep = $('00 Prepare').item.json;
const telegramChatId = prep.telegramChatId;
const httpItem = items[0];
const err = httpError(httpItem);
if (err) {
  return [{ json: { status: 'failed', response: 'Tool failed: Yes\n' + 'Tool used: WF_EMAIL_LIST_CONTEXT (list)\n' + 'Error message: ' + (err) + '\n' + 'Action taken: None\n' + 'Verification status: Failed', verificationStatus: 'Failed' } }];
}
const data = httpItem.json || {};
const rows = Array.isArray(data.value) ? data.value : [];

// Persist the numbered list per telegram chat id using workflow static data.
const store = $getWorkflowStaticData('global');
if (!store.emailLists) store.emailLists = {};
const nowIso = berlinNow();
const list = rows.map((m, i) => ({
  listNumber: i + 1,
  message_id: m.id || '',
  conversationId: m.conversationId || '',
  subject: m.subject || '(no subject)',
  senderName: (m.from && m.from.emailAddress && m.from.emailAddress.name) || '',
  senderEmail: (m.from && m.from.emailAddress && m.from.emailAddress.address) || '',
  receivedDateTime: m.receivedDateTime || '',
  isRead: !!m.isRead,
  hasAttachments: !!m.hasAttachments,
  webLink: m.webLink || '',
  bodyPreview: (m.bodyPreview || '').slice(0, 200),
  createdAt: nowIso,
  telegramChatId,
}));
store.emailLists[telegramChatId] = { savedAt: nowIso, items: list };

if (list.length === 0) {
  return [{ json: { status: 'ok', count: 0, response: 'No emails were returned by the Inbox.\nVerification status: Passed', verificationStatus: 'Passed' } }];
}

const lines = list.map(e =>
  `Email ${e.listNumber}: ${e.subject}\n  From: ${e.senderName || e.senderEmail}\n  Received: ${e.receivedDateTime}\n  Read: ${e.isRead ? 'Read' : 'Unread'} | Attachments: ${e.hasAttachments ? 'Yes' : 'No'}`
);
return [{ json: {
  status: 'ok',
  count: list.length,
  items: list,
  response: `Saved numbered email list (${list.length}) for this chat.\n\n` + lines.join('\n') + '\n\nVerification status: Passed',
  verificationStatus: 'Passed'
} }];

