const telegramChatId = prep.telegramChatId;
const emailNumber = prep.emailNumber;
const requestType = prep.requestType;

if (!emailNumber || emailNumber < 1) {
  return [{ json: { status: 'failed', response: 'No valid email number was provided. Please tell me which email number (for example Email 2).\nVerification status: Failed', verificationStatus: 'Failed' } }];
}
const store = $getWorkflowStaticData('global');
const saved = store.emailLists && store.emailLists[telegramChatId];
if (!saved || !Array.isArray(saved.items) || saved.items.length === 0) {
  return [{ json: { status: 'expired', response: 'The saved email list expired or was never created for this chat. Please ask me to list your emails again.\nVerification status: Failed', verificationStatus: 'Failed' } }];
}
const found = saved.items.find(e => Number(e.listNumber) === Number(emailNumber));
if (!found) {
  return [{ json: { status: 'not_found', response: `Email number ${emailNumber} was not found in the saved list. Please list your emails again.\nVerification status: Failed`, verificationStatus: 'Failed' } }];
}
return [{ json: {
  status: 'ok',
  requestType,
  emailNumber,
  message_id: found.message_id,
  conversationId: found.conversationId,
  subject: found.subject,
  senderName: found.senderName,
  senderEmail: found.senderEmail,
  receivedDateTime: found.receivedDateTime,
  isRead: found.isRead,
  hasAttachments: found.hasAttachments,
  webLink: found.webLink,
  bodyPreview: found.bodyPreview,
  response: `Resolved Email ${emailNumber} from saved memory.\nSubject: ${found.subject}\nFrom: ${found.senderName || found.senderEmail}\nmessage_id: ${found.message_id}\nAttachments: ${found.hasAttachments ? 'Yes' : 'No'}\nUse this exact message_id for follow-up actions (requestType=${requestType}).\nVerification status: Passed`,
  verificationStatus: 'Passed'
} }];
